$ErrorActionPreference='Stop';$values=@{};Get-Content .env|ForEach-Object{if($_ -match '^([^#=]+)=(.*)$'){$values[$matches[1]]=$matches[2]}}
$login=Invoke-RestMethod -Method Post -Uri 'http://localhost:20200/api/v1/auth/login' -ContentType 'application/json' -Body (@{email=$values.TEST_ACCOUNT_EMAIL;password=$values.TEST_ACCOUNT_PASSWORD}|ConvertTo-Json);$headers=@{Authorization="Bearer $($login.access_token)"}
function Invoke-Loop([string]$mode,[int]$maxSteps){$session=Invoke-RestMethod -Method Post -Uri 'http://localhost:20200/api/v1/sessions' -Headers $headers -ContentType 'application/json' -Body (@{title="Agent loop $mode";model='workama-chat';max_steps=$maxSteps}|ConvertTo-Json);$ticket=Invoke-RestMethod -Method Post -Uri "http://localhost:20200/api/v1/sessions/$($session.id)/ws-tickets" -Headers $headers;$url="ws://localhost:20201/ws/sessions/$($session.id)?ticket=$([uri]::EscapeDataString($ticket.ticket))";$result=node tools/agent-loop-smoke.mjs $url $login.access_token $session.id $mode|ConvertFrom-Json;if(-not $result.ok){throw "Agent loop $mode failed"};return $result}
$resume=Invoke-Loop 'resume' 5;$cancel=Invoke-Loop 'cancel' 5;$maximum=Invoke-Loop 'max' 2
$evidence=[ordered]@{timestamp=[DateTimeOffset]::UtcNow.ToString('o');plan_completed=$resume.ok;task_versions_monotonic=$resume.task_versions_monotonic;thought_steps=$resume.thought_count;pause_resume=$resume.paused -and $resume.resumed;cooperative_cancel=$cancel.cancelled;cancelled_remaining_tasks=@($cancel.final_tasks|Where-Object status -eq 'cancelled').Count;max_steps_blocked=$maximum.max_blocked};$evidence|ConvertTo-Json -Depth 8|Set-Content quality/evidence/agent-core-loop-smoke.json;$evidence|ConvertTo-Json -Depth 8
